pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / tight fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small post-residuals are good, but residual below the
        // minimum plausible item size is wasted unless it's exactly 0.
        if post_residual < 10 {
            score += 8.0; // fragment too small for any item
        }
    }

    // 2-step lookahead: strongly reward bins whose post-residual exactly fits
    // or comfortably holds the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 0.5; // next item fits here: good, less so with big slack
        } else {
            // next item won't fit: penalize proportionally to how close we came
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.8;
        }
    }

    // Compare against mean residual: bins with residual far below mean are
    // "almost full" — prefer filling them rather than leaving them stranded.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let below_mean = mean_residual - resid_f;
        if below_mean > 0.0 {
            score -= below_mean * 0.6;
        } else {
            score += (-below_mean) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when nothing decent exists, i.e. when
    // the item is large relative to available residuals or many bins are open.
    if bin_residual == bin_capacity {
        score += 40.0; // mild baseline penalty for opening a new bin
        if next_item_size > 0 {
            // A fresh bin is good if the current item plus next item nearly fill it.
            let pair = item_size as f64 + next_item_size as f64;
            if pair >= bin_capacity as f64 * 0.9 {
                score -= 250.0;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 30.0;
        }
    }

    score
}

