            score -= 6.0;
        } else if next_gap > 25 {
            score += 3.0;
        }
    }

    // Late-stream tightening — reward draining nearly-full bins more
    // aggressively to avoid leaving many small fragments at the end.
    if progress > 0.85 && bin_residual != bin_capacity {
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        if fill > 0.7 {
            score -= 4.0 * fill;
        }
    }

    // NEW: two-item lookahead chain depth — if after placing the next item
    // the residual still fits a third common item band (>= 8), the bin is a
    // high-value host; reward proportionally to remaining usable space.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next >= 8 && after_next <= 30 {
            score -= (after_next as f64) * 0.35;
        }
    }

    // NEW: stranded-fragment risk weighted by how many bins still fit —
    // when few bins fit, wasting residual space is costlier.
    if post_residual > 0 && post_residual < 12 && fitting_bins_count <= 2 {
        score += 8.0;
    }

    // NEW: endgame exactness — near the stream's end, only near-perfect
    // fits should win; penalize loose fits harder.
    if progress > 0.9 && post_residual > 15 {
        score += (post_residual as f64 - 15.0) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap; // normalized post residual in [0,1]

    // Base: minimize wasted space, weighted non-linearly by stream progress.
    let mut score = pr * (0.6 + 1.2 * progress * progress);

    // Smooth non-linear penalty for residual too small to ever be useful:
    // dead-space term grows when prn is small but nonzero.
    score += 25.0 * prn * (1.0 - prn) * (1.0 - prn) * (1.0 - progress);

    // Reward near-perfect fills (prn close to 0) more strongly late in stream.
    score -= 18.0 * (1.0 - prn).powi(6) * (0.4 + 0.6 * progress);

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // from the mean (tighter bins get priority), smooth quadratic coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 6.0 * dev * (0.5 + progress);

    // Lookahead: bonus if post residual can still fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 6.0 * (1.0 - progress) * (post_residual - next_item_size) as f64 / cap;
    } else if next_item_size > 0 {
        // penalize blocking the next item, smoothly
        score += 4.0 * (next_item_size - post_residual) as f64 / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress - 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= ~10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium dead space (fits only tiny items) is also heavily penalized.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize if post residual is just barely too small for the next item
    // (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make an empty bin attractive only when the item
    // is large (would leave an awkward residual elsewhere) or when mean
    // residual across open bins is already small (nothing fits well).
    if bin_residual == bin_capacity {
        let base = 55.0
            + 0.3 * open_bins_count as f64
            - 0.5 * mean_residual
            - 20.0 * fill;
        // If the item would leave a small unusable gap in any bin anyway,
        // opening fresh is fine.
        if post_residual < 20 {
            score = base - 30.0;
        } else {
            score = base;
        }
    } else {
        // Slight preference for bins whose residual is close to the item
        // (best-fit flavor, scaled by residual tightness).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it decomposes into
    // "nice" denominations (divisors of capacity). Residuals divisible by
    // 50/25/20/10 are more reusable by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that sit on harmonic grid points.
    if post_residual % 50 == 0 { score -= 6.0; }
    else if post_residual % 25 == 0 { score -= 4.0; }
    else if post_residual % 20 == 0 { score -= 3.0; }
    else if post_residual % 10 == 0 { score -= 2.0; }

    // Penalize awkward residual classes via modulo coupling.
    let awkward = (post_residual % 7) as f64;
    score += 0.3 * awkward;

    // Perfect fit is always excellent.
    if post_residual == 0 { score -= 15.0; }

    // Dead-space penalty: tiny residuals are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let fill_ratio = nxt / pr.max(1.0);
            // reward high fill of the leftover, penalize leaving tiny crumbs
            score -= 4.0 * fill_ratio;
            let crumb = pr - nxt;
            if crumb > 0.0 && crumb < 10.0 {
                score += 5.0;
            }
            // harmonic check of the crumb after the lookahead item
            let crumb_u = crumb as u32;
            if crumb_u % 25 == 0 || crumb_u % 20 == 0 { score -= 2.0; }
        } else {
            // next item won't fit here; residual will carry forward.
            // Slight penalty proportional to how far off it is, scaled
            // by stream progression (early on, keep bins flexible).
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 2.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: default score is full capacity residual (100).
    // Only prefer a new bin when the best existing fit is very poor.
    if bin_residual == bin_capacity {
        // neutralize base, then evaluate: opening a new bin is attractive
        // if item is large and would leave huge unusable space elsewhere,
        // but wasteful when many bins are lightly loaded.
        score = 0.0;
        score += 20.0 * (item_size as f64 / cap); // large items prefer existing bins
        score -= 1.5 * open_bins_count as f64;    // many open bins -> reuse them
        score += if mean_residual > 40.0 { 6.0 } else { 0.0 };
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 3.0; // fresh bin can chain with next item
        }
        // small harmonic bonus for a fresh bin's residual class
        if item_size % 25 == 0 || item_size % 20 == 0 { score -= 2.0; }
    }

    // Mild preference for tighter bins overall (waste minimization).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Smallest conceivable item is 1; a residual below a practical floor
    // (e.g. < 10) is nearly dead space — add a steep nonlinear penalty.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // Moderately awkward gap zone: superlinear penalty.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits strongly (waste-avoidance flip side).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Coupling with next item lookahead: if the next item fits exactly
    // into the post_residual, this bin is highly valuable — reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Perfect chain fit: next item exactly consumes the gap.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }
    // Penalize if next item cannot use the gap and gap is small.
    if next_item_size > post_residual && post_residual < 15 {
        score += 8.0;
    }

    // Open-bins pressure: discourage spreading across many open bins;
    // more open bins => prefer filling existing bins (raise all scores
    // slightly relative to new-bin option via dead-space penalty scaling).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if post_residual > 0 {
        score *= 1.0 + 0.03 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor
    // using it rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Make the fresh-bin option mildly unattractive unless the item is
    // large and no good fit exists, so we avoid premature bin sprawl.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 10.0 * progress;
        // If item is large relative to capacity, opening fresh may be wise.
        if (item_size as f64 / bin_capacity as f64) > 0.6 {
            score -= 20.0;
        }
        // If many bins fit the item, definitely prefer an existing bin.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mean residual context: if average residual is high, tightening
    // fits matters more; scale the waste term accordingly.
    if mean_residual > 0.0 {
        score += 0.05 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: partition dead space into usable classes
    // Class boundaries at multiples of capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual as f64;

    // Items in the next stream typically 1..=100; residual usable if it can
    // host a "harmonic class" of item sizes.
    if post_residual > 0 {
        // Dead-space penalty grows super-linearly in the awkward mid-range
        // (residual too small to be useful, too large to ignore).
        if post_residual < quarter {
            score += 40.0 - post; // small leftovers: heavily penalize
        } else if post_residual < half {
            score += 10.0; // awkward middle class
        } else {
            score -= 5.0; // large residual: still flexible
        }

        // Modulo arithmetic: residuals divisible by common item classes (10/20/25/50)
        // are "harmonic" and likely reusable.
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: reward leaving exactly next_item_size, or a class
    // that still fits the next item after some margin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect lookahead fit
        } else if post_residual >= next_item_size {
            // next item fits here afterward: mild reward scaled by slack
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportional to waste
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or residual after placement is very generous.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) / (mean_residual / bin_capacity as f64 + 1.0);
        let pressure = (mean_residual / bin_capacity as f64) - 0.5 * progress;
        // Penalize new bins when existing mean residual is healthy
        score += 30.0 + pressure * 20.0 - crowded * 0.5;
        // A fresh bin is good if the item is large and would leave bad residue elsewhere
        if item_size > half {
            score -= 15.0;
        }
    }

    // Prefer tighter existing bins: smaller bin_residual relative to item
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    // Mild preference for bins below mean residual (keep spread balanced)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no future item can use
