    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 8.0;

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good; encourage closing out existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., leaving this bin as the "roomy" outlier) is penalized mildly.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.05;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // prefer it when existing bins would leave badly fragmented space.
    if bin_residual == bin_capacity {
        // Neutral base plus mild pressure so poor fits into open bins win.
        score = bin_capacity as f64 * 0.6 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
    }

