    // are unusable. Penalize hard, scaled by how "wasted" the gap is.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual < 20 {
        // Marginal zone: small gaps are only useful for tiny items.
        score += 8.0 + (20 - post_residual) as f64 * 0.8;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect match with lookahead: strongly favor bins that leave exactly
    // room for (or are consumed by) the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space relative to lookahead.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening new bins is cheap so prefer tight fits there.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by pressure and by how much space would
        // be left idle relative to mean residual of existing bins.
        score += 20.0 + pressure * 6.0;
        if post_residual > 0 {
            score += mean_residual.max(0.0) * 0.2;
        }
    } else {
        // Existing bin: reward using it, more so under high pressure.
        score -= 5.0 + pressure * 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack);
    }

    // Penalize leftovers that the next item cannot use (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
        // Small residuals are likely unusable forever.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Reward tightening bins relative to mean residual (balance fragmentation).
    let prog = step_index as f64 / total_items as f64;
    if (post_residual as f64) < mean_residual {
        score -= 10.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 8.0 * ((post_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Late in the stream, avoid opening new bins; consolidate.
    if prog > 0.8 && bin_residual != bin_capacity {
        score -= 20.0 * prog;
    }

    // Mild penalty for opening a brand-new bin when others could fit.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - prog);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize creating small dead space that likely can't fit future items
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead) / 10.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Next item won't fit here afterwards; slight penalty unless residual is large anyway
        score += 5.0;
    }

    // Scarcity: this bin is the only one that fits -> strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    } else if fitting_bins_count >= 2 {
        // Among many candidates, prefer tightest fit (post_residual already does this)
        score += 2.0 * (fitting_bins_count as f64).sqrt();
    }

    // New-bin candidate handling: opening a bin is costly when existing bins fit well
    if bin_residual == bin_capacity {
        // Baseline cost of a new bin; allow opening when item is large / fits poorly elsewhere
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 45.0 + 30.0 * (1.0 - progress);
        // Prefer new bin if item is big relative to capacity (poor fit elsewhere anyway)
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            open_cost -= 20.0;
        }
        // If mean residual across open bins is small, opening is reasonable
        if mean_residual < item_size as f64 {
            open_cost -= 15.0;
        }
        score += open_cost;
    } else {
        // Slight preference for bins already partially filled (reduce bin count)
        score -= 3.0;
        // Encourage using bins with residual close to item size (best-fit sharpening)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness;
    }

    // Late stream: consolidation pressure — favor filling existing bins harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: mild quadratic growth penalizes large residuals; Late: stronger.
    let p = progress * progress;
    score += 0.8 * pr * p + 0.5 * (pr * pr) / cap * progress;

    // Reward tight fits: subtract a smooth function of item/capacity.
    let tight = (item_size as f64 / cap).powi(3);
    score -= 12.0 * tight * (1.0 + p);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 4.0 * (ni - pr) / cap * (1.0 + 2.0 * p);
        } else {
            score -= 2.0 * (pr - ni) / cap * (1.0 - 0.5 * p);
        }
    } else {
        // Last item: strongly prefer filling existing bins.
        score -= 15.0 * (item_size as f64 / cap);
    }

    // Last-chance bin bonus: smooth reward when few bins fit.
    if fitting_bins_count <= 1 {
        score -= 6.0 * (1.0 - p * 0.5);
    }

    // Mild penalty for proliferating open bins late in the stream.
    score += 0.3 * open_bins_count as f64 * p;

    // Align with mean residual: prefer bins whose residual is below average.
    score += 0.5 * (mean_residual - pr) * (0.5 + p);

    // New-bin candidate: keep neutral baseline, slightly penalized early
    // so we prefer packing, but becomes competitive late.
    if bin_residual == bin_capacity {
        score += 5.0 - 8.0 * p;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: classify leftover space ---
    // Class 0: perfect fit (post_residual == 0) -> huge reward
    // Class 1: small leftover (1..=10) -> strong reward
    // Class 2: medium leftover (11..=30) -> mild reward
    // Class 3: large leftover (>30) -> penalty (dead space risk)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    } else {
        score += 8.0;
    }

    // --- Integer-division thresholds on post_residual vs next_item_size ---
    // If the next item can exactly fill the leftover, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 15.0;
            } else if slack <= 30 {
                score -= 3.0;
            } else {
                score += 4.0;
            }
        } else {
            // Next item cannot use this residual at all: leftover is stranded
            // for at least one step -> penalize proportionally.
            score += 6.0 + (post_residual as f64) * 0.15;
        }
    }

    // --- Modulo arithmetic on post_residual: "harmonic" residue classes ---
    // Residuals divisible by 10 pair well with typical item sizes (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd tiny residuals (1..9 non-multiples) are hard to fill: slight penalty.
    if post_residual < 10 && post_residual % 10 != 0 && post_residual > 0 {
        score += 3.0;
    }

    // --- Capacity fraction coupling: prefer bins whose fill level crosses
    // harmonic fraction thresholds (1/2, 3/4) of capacity ---
    let used = bin_capacity - bin_residual;
    let fill_after = bin_capacity - post_residual;
    let half = bin_capacity / 2;
    let three_quarters = (bin_capacity * 3) / 4;
    if used < half && fill_after >= half {
        score -= 10.0;
    }
    if used < three_quarters && fill_after >= three_quarters {
        score -= 12.0;
    }

    // --- Last-chance bonus: only this bin fits the item ---
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive late in the stream when open
        // bins are fragmented (high mean residual spread) or nothing fits well.
        let progress = step_index as f64 / total_items as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening new bins mildly; relax penalty as fragmentation grows.
        score = 60.0 + 40.0 * progress - 30.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if post_residual % 10 == 0 {
            score -= 2.0; // fresh bin keeps clean harmonic residual
        }
    }

    // --- Slight preference to keep number of open bins small early on ---
    score += 0.5 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    } else if post_residual < 20 {
        score += 25.0; // very tight gap, only tiny items fit
    } else if post_residual < 35 {
        score += 8.0;  // moderately risky gap
    } else {
        // Larger usable residuals are mildly attractive: subtract a bit
        // so bins with room for future items are preferred over new bins.
        score -= 4.0;
    }

    // Reward a perfect or near-perfect fit strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the resulting
    // residual, this placement is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            score += 10.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // the new-bin candidate (bin_residual == bin_capacity) gets penalized
    // proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + 6.0 * open_bins_count as f64;
        // But if no open bin fits well (item much larger than mean residual),
        // soften the pressure so a fresh bin can win.
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 20.0;
        }
    }

    // Mild stream-progression term: early on, be slightly more willing to
    // open bins (low step_index), later consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly matches the post residual,
    // this bin is ideal (chains two items perfectly).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here later: mild reward proportional to tightness.
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot fit in the leftover: penalize dead space,
            // scaled by how much is wasted relative to mean residual.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(80.0);
        }
    }

    // Penalize small unusable residuals (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: bins with residual far below mean are
    // "tighter" and better to fill; bins above mean are loose.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Early in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    // Slight penalty per open bin to discourage bin proliferation.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose residual is nearly consumed.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // if post-residual is dead space the next item can never use, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 12.0; // tiny dead space, likely unusable
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins; few bins -> opening new is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline already penalized via post_residual.
        // Make it more attractive early (exploration) and when bins are scarce.
        score -= 15.0 * (1.0 - progress) + 2.0 * (open_bins_count.max(1) as f64).ln();
        // But discourage new bins when existing bins are quite empty overall.
        if mean_residual > 50.0 && fitting_bins_count > 0 {
            score += 20.0;
        }
    } else {
        // Existing bin: reward when mean residual is high (consolidation needed).
        score -= 5.0 * (mean_residual / bin_capacity as f64);
        // Late in the stream, waste less; keep bins closeable.
        score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild preference for bins with moderate residual vs huge residual.
    let res_ratio = bin_residual as f64 / bin_capacity as f64;
    score += 6.0 * res_ratio * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 12.0 * norm_pr * norm_pr * (1.0 + t);
    score -= 8.0 * (norm_pr * (1.0 - t)) * (norm_pr * (1.0 - t));

    // Reward tight fits, scaled by progress
    let fit_quality = 1.0 - norm_pr;
    score -= 15.0 * fit_quality * fit_quality * (0.5 + t);

    // Last-chance bin bonus (stronger early when opening bins is costly later)
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - t);
    }

    // Penalize bins whose residual deviates from mean (fragmentation)
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - t) - 3.0 * t;
        } else {
            let waste = (next_item_size - post_residual) as f64 / cap;
            score += 9.0 * waste * waste;
        }
    }

    // Mild penalty for many open bins late in stream
    score += 0.4 * open_bins_count as f64 * t;

    // New-bin candidate: keep neutral-ish, penalize slightly unless nothing fits well
    if bin_residual == bin_capacity {
        score += 2.0 + 20.0 * fit_quality * (1.0 - fit_quality);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity-fraction bands.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left

    // Modulo arithmetic on post_residual: residuals that are "nice" (small,
    // or exact multiples of common item sizes) are more reusable.
    let pr_u = post_residual;
    let mod10 = (pr_u % 10) as f64;
    let mod20 = (pr_u % 20) as f64;

    // Penalize awkward residuals: not small, not aligned to common item sizes.
    let awkward = if pr_u == 0 {
        -50.0 // perfect fit, best possible
    } else if pr_u < 10 {
        -8.0 // too small for any item: dead space, but tiny
    } else {
        // alignment bonus: residuals divisible by 10 or 20 pair well with
        // typical item granularities
        -(20.0 - mod10) * 0.15 - (40.0 - mod20) * 0.05
    };
    score += awkward;

    // Integer division threshold: classify residual into harmonic bands
    // (0-10 dead, 10-25 poor, 25-50 medium, 50+ good).
    let band = pr_u / 25; // 0,1,2,3+
    score -= band as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr_u {
            score -= 30.0;
        } else if next_item_size <= pr_u {
            let slack = (pr_u - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: penalize leaving medium residual
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits well.
        // Score it mildly above well-fitting existing bins.
        score = 0.55 * cap + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        // Late in the stream, prefer compacting into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild preference to fill fuller bins first (tighten packing).
    score += 0.1 * (1.0 - (bin_residual as f64) / cap) * -1.0;

    // Mean-residual coupling: when open bins are collectively full,
    // discourage spreading; when residuals are large, allow consolidation.
    if mean_residual > 0.0 {
        score += 0.05 * (mean_residual - pr).max(-20.0).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        // Perfect/near-perfect fill: reward strongly.
        score -= 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        score -= 100.0;
    } else {
        // Usable residual: mild preference for smaller leftovers, nonlinear.
        let p = post_residual as f64;
        score += 0.05 * p * (1.0 + p / 200.0);
    }

    // Reward bins whose residual is "tuned" to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * tightness;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < dead_threshold {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    }
    // Penalize if next item cannot use the leftover at all (dead space for k=2).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and stream progresses.
        score += 15.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
        // But if no existing bin fits well (large dead space would be created elsewhere),
        // opening a fresh bin becomes attractive when mean residual is low.
        score -= 0.2 * mean_residual;
    } else {
        // Existing bin: reward reuse, scaled by number of open bins.
        score -= 1.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (consolidate fuller bins).
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead core ----
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-step match: post_residual exactly fits the next item.
        // Strongly reward (subtract) so this bin is chosen.
        let match_diff = (post - next).abs();
        if post >= next {
            // Next item fits here afterward: reward closeness to a perfect pair.
            score -= 60.0 * (1.0 - match_diff / bin_capacity as f64);
            // Exact match gets an extra bonus.
            if match_diff < 0.5 {
                score -= 40.0;
            }
        } else {
            // Next item does NOT fit the leftover: penalize dead space,
            // more so when the leftover is small and unusable.
            let dead = post / bin_capacity as f64;
            score += 25.0 * (1.0 - dead) * (1.0 + progress);
            // Extra penalty if leftover is below the minimum plausible item size.
            if post < 1.0 {
                score += 15.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // ---- Relative-to-mean coupling ----
    // Bins with residual far below mean are "tight" — placing here is efficient
    // if it nearly empties the bin; reward near-emptying.
    let post_f = post_residual as f64;
    if post_f <= mean_residual {
        score -= 10.0 * (1.0 - post_f / (mean_residual + 1.0));
    } else {
        score += 5.0 * ((post_f - mean_residual) / bin_capacity as f64);
    }

    // ---- Last-chance bin bonus ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; avoid opening a new bin.
        score -= 35.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Brand-new empty bin: default mildly attractive.
        score = 45.0;
        // Prefer a new bin when existing fits are poor (large post_residual
        // relative to next item, or many open bins with slack).
        if next_item_size > 0 {
            let waste = post_residual as f64; // = capacity - item_size for new bin
            let avg_open_fit = if open_bins_count > 0 { mean_residual } else { 0.0 };
            // If open bins would leave very little usable room, favor new bin.
            if avg_open_fit < item_size as f64 * 1.2 && open_bins_count > 0 {
                score -= 20.0;
            }
            if waste as u32 <= next_item_size {
                score -= 10.0; // new bin also pairs well with next item
            }
        }
        // Late in the stream, consolidating into open bins is cheaper.
        score += 15.0 * progress;
        // Fewer open bins -> slightly prefer reusing them instead.
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // ---- Tight-fit reward: placing item that almost fills the bin ----
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 20.0 * (fill_ratio - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (tight packing).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize large dead space nonlinearly.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste * waste;
    }

    // Perfect fill is extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving a medium gap slightly
            score += 8.0;
        }
    } else {
        // Last item: any residual is pure waste; minimize it hard.
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // More competing bins -> prefer the tightest, mild scaling.
    score += 2.0 * (fitting_bins_count.saturating_sub(1)) as f64;

    // Time horizon: early in the stream, be conservative with open bins;
    // late in the stream, pack tighter since fewer chances remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 25.0 * progress * (1.0 - fit_ratio);

    // Global state coupling: if mean residual is high, encourage consolidation
    // into existing bins rather than spreading.
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate: opening a bin is costly unless item is large or
    // nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        let open_penalty = 55.0
            - 0.3 * (item_size as f64)
            - 20.0 * progress
            + 3.0 * (fitting_bins_count as f64);
        score += open_penalty;
        // If next item is small, new bin is less attractive (existing gaps suffice).
        if next_item_size > 0 && next_item_size <= mean_residual {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight fit)
    let mut score = post;

    // Normalized post-residual
    let pr = post / cap;

    // Smooth polynomial coupling: penalize mid-range dead space more via quadratic term
    score += 12.0 * pr * pr * (1.0 - 0.5 * progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    let tightness = 1.0 - pr;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Perfect fit bonus (post_residual near zero), smoothly scaled
    if post == 0 {
        score -= 25.0 * (0.6 + progress);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening a new bin, unless current fit is poor
    // (bin_residual == bin_capacity means empty candidate bin)
    if bin_residual == bin_capacity {
        let fit_quality = item / cap; // larger item -> new bin more acceptable
        let poor_fit = (pr - 0.5).abs(); // how far from ideal half-fill after placement
        score += 20.0 * (1.0 - fit_quality) + 10.0 * poor_fit * (1.0 - progress);
        // Late in stream, opening new bins is less costly
        score -= 8.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balance), smooth coupling
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 - progress);

    // Lookahead: if next item could use this bin's post residual, reward leaving useful space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = (post - nxt) / cap;
            score -= 8.0 * (1.0 - gap * gap) * (0.4 + 0.6 * progress);
        } else {
            // post residual too small for next item: mild penalty for wasted space
            score += 3.0 * pr * (0.5 + progress);
        }
    }

    // Slight preference for bins that are already fairly full (consolidation)
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 3.0 * fill * fill * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10 units.
    let post_class = post_residual / 10;
    let next_class = next_item_size / 10;

    // Reward when the next item's class matches the post residual class (perfect modular fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post_residual as i64 - next_item_size as i64;
        // Strong reward if next item fits leaving a small, "harmonic" remainder
        if diff <= 10 {
            score -= 30.0 + (10 - diff) as f64 * 2.0;
        } else if diff <= 20 {
            score -= 10.0;
        }
        // Penalize if next item's class is far above the post residual class (wasted gap)
        if next_class > post_class + 1 {
            score += (next_class - post_class) as f64 * 4.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover space: penalize dead space creation
        score += post_residual as f64 * 0.5;
    }

    // Fraction-of-capacity coupling: reward tight fits relative to capacity
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= fill_fraction * 15.0;

    // Integer-division threshold on post_residual: residues in (0..5) are near-perfect
    if post_residual < 5 {
        score -= 25.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        // Harmonic residue: multiple of 10, easy for future items
        score -= 8.0;
    } else if post_residual % 10 >= 8 {
        score -= 4.0;
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream,
    // especially when open bins exist and the item is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + item_size as f64 * 0.3;
        if open_bins_count > 0 {
            score += (open_bins_count as f64).sqrt() * 10.0 * (1.0 - progress);
        }
        // Late in the stream, opening a fresh bin is cheaper
        score -= progress * 20.0;
    }

    // Mild penalty for bin whose residual is far from mean residual (imbalance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual below the minimum plausible item size (1) is impossible here,
    // but tiny gaps (1..=10) are practically dead space for most streams.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0) + 25.0;
    } else if post_residual <= 20 {
        // Moderately dead zone: still hard to fill with unknown-distribution items.
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (perfect fill is ideal).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * tightness * tightness;
    }

    // Open-bin pressure: discourage spreading when many bins are already open,
    // but encourage using existing bins over opening new ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make opening a new bin costly unless the item is huge
    // and no existing bin gives a decent fit.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 3.0;
        let fit_quality = if item_size as f64 / bin_capacity as f64 > 0.85
            && (fitting_bins_count == 0 || mean_residual < item_size as f64 * 1.05) {
            -20.0
        } else {
            0.0
        };
        score += 50.0 + pressure + fit_quality;
    }

    // Lookahead coupling: if the next item fits snugly into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 20.0;
            } else {
                score -= 10.0 * (1.0 - slack as f64 / post_residual.max(1) as f64);
            }
        } else if post_residual > 0 && post_residual < 10 {
            score += 15.0; // dead space confirmed by lookahead
        }
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // to keep the bin pool homogeneous and easy to fill later.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Early-stream: slightly prefer filling existing bins aggressively early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: perfect-fit reward (minimize post residual aggressively)
    score -= (bin_residual - post_residual) as f64 * 0.5;

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward proportional to how snugly it fits
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - chain_waste * 0.3;
        } else {
            // next item won't fit here: penalize leaving dead space
            let dead = (post_residual as f64 / bin_capacity as f64).powf(2.0);
            score += 10.0 + dead * 30.0;
        }
    }

    // Penalize bins whose residual deviates below the mean (fragmented bins)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when residuals are large (item fits nowhere snugly)
    if bin_residual == bin_capacity {
        // new bin baseline: post_residual == capacity - item_size
        // discourage opening new bins when a decent fit exists
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer bins that end with small residual (tight fit reward).
    let tightness = if post_residual == 0 {
        -40.0
    } else {
        -8.0 * (1.0 - post_residual as f64 / bin_capacity as f64)
    };
    score += tightness;

    // Penalize residuals too small for the smallest conceivable follow-up item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (post_residual as f64 / next_item_size as f64);
        } else {
            // next item won't fit here: mildly penalize wasting large residual on small item
            score += 0.1 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: cost of opening grows with open bins and remaining stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_cost = 45.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        score += new_bin_cost;
        // But if the item is huge and mean residual is small, a fresh bin is attractive.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0; // next item won't share a fresh bin either
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating.
    let pressure = (mean_residual - post_residual as f64).abs();
    score += 0.05 * pressure;

    // Time horizon: early in stream, be pickier about large residuals (keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.15 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late in the stream, penalize residual more strongly.
    let coupling = 1.0 + 3.0 * progress * progress + 2.0 * progress * norm_pr;
    score *= coupling;

    // Dead-space penalty: residual too small to likely fit future items (non-linear falloff).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (nxt - pr).max(0.0) / cap;
        score += 30.0 * gap * gap;
        // Bonus if this bin exactly accommodates the next item too.
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 12.0 * fit_next * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize spreading across many open bins; reward consolidation (smooth in open count).
    let open_norm = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 10.0 * open_norm * norm_pr;

    // Nudge toward bins below the mean residual (filling emptier bins evenly).
    score += 2.0 * (mean_residual - pr) / cap;

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: partition dead space into usable classes
    // Class boundaries at multiples of capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual as f64;

    // Items in the next stream typically 1..=100; residual usable if it can
    // host a "harmonic class" of item sizes.
    if post_residual > 0 {
        // Dead-space penalty grows super-linearly in the awkward mid-range
        // (residual too small to be useful, too large to ignore).
        if post_residual < quarter {
            score += 40.0 - post; // small leftovers: heavily penalize
        } else if post_residual < half {
            score += 10.0; // awkward middle class
        } else {
            score -= 5.0; // large residual: still flexible
        }

        // Modulo arithmetic: residuals divisible by common item classes (10/20/25/50)
        // are "harmonic" and likely reusable.
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: reward leaving exactly next_item_size, or a class
    // that still fits the next item after some margin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect lookahead fit
        } else if post_residual >= next_item_size {
            // next item fits here afterward: mild reward scaled by slack
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportional to waste
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or residual after placement is very generous.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) / (mean_residual / bin_capacity as f64 + 1.0);
        let pressure = (mean_residual / bin_capacity as f64) - 0.5 * progress;
        // Penalize new bins when existing mean residual is healthy
        score += 30.0 + pressure * 20.0 - crowded * 0.5;
        // A fresh bin is good if the item is large and would leave bad residue elsewhere
        if item_size > half {
            score -= 15.0;
        }
