        score -= 12.0 + 0.1 * next_item_size as f64;
    }
    // If next item is slightly too big, mild penalty (fragmentation risk).
    if next_item_size > post_residual && next_item_size > 0 && next_item_size - post_residual <= 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // is large and no open bin is a good host.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let mean_frac = mean_residual / cap;
        // Penalize new bins generally; discount penalty when open bins are very full.
        let mut nb = 45.0 - 30.0 * mean_frac;
        // Large items waste less space in a fresh bin.
        nb -= 20.0 * item_frac;
        // Late in the stream, prefer compacting into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 20.0 * progress;
        // If item fits almost perfectly in a fresh bin (item == capacity edge), fine.
        if item_frac > 0.8 {
            nb -= 25.0;
        }
        score += nb.max(0.0);
    }

    // Slight preference for fuller bins when many bins are open (consolidation).
    score -= 0.05 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fit: strong reward.
