    if post_residual > 0 && post_residual < 10 {
        score += 75.0;
    } else if post_residual < 20 {
        score += 30.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // 2-step lookahead: chain fits with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score -= 20.0;
            } else if after_next < 20 {
                score -= 10.0;
            } else {
                score -= 6.0;
            }
        } else {
            let stranded = (next_item_size - post_residual) as f64;
            score += 8.0 + stranded.min(30.0) * 0.3;
        }
        if post_residual > next_item_size && (post_residual - next_item_size) <= 2 && (post_residual - next_item_size) > 0 {
            score -= 8.0;
        }
    }

    // Compare against mean residual: tighter bins preferred.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Fit-ratio term: reward tight packing independent of absolute sizes.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 18.0;
        } else if fill_ratio > 0.7 {
            score -= 7.0;
        } else if fill_ratio < 0.3 {
            score += 6.0;
