    // Last-chance bin: sole fitting open bin beats opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 65.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        score += 14.0 + 6.0 * open_bins_count as f64;
        // Poor fits everywhere: a fresh bin is justified.
        if (item_size as f64) > mean_residual.min(bin_capacity as f64) - 5.0 {
            score -= 26.0;
        }
        if progress > 0.85 {
            score -= 12.0;
        }
        if progress < 0.3 && open_bins_count > 4 {
            score += 8.0;
        }
        // NEW: if the next item is large and no residual can hold it,
        // reserving fresh space now is cheap insurance.
        if next_item_size as f64 > mean_residual.max(1.0) {
            score -= 9.0;
        }
        // NEW: when many bins are open with large mean residual, prefer
        // consolidating into them rather than proliferating.
        if open_bins_count > 6 && mean_residual > item_size as f64 + 4.0 {
            score += 10.0;
        }
    }

    // Consolidation pressure grows as the stream progresses.
    score += progress * (mean_residual - post_residual as f64) * 0.25;

    // Slight penalty per open bin to discourage proliferation.
    score += 0.1 * open_bins_count as f64;

    // NEW: residual-dead-space ratio term — leftover relative to capacity
    // that cannot plausibly host the next item is dead weight; penalize
    // proportionally, reward when it can.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
        score += 20.0 * unusable.min(0.2);
    } else if post_residual >= next_item_size && next_item_size > 0 {
        score -= 2.0 * (post_residual as f64 / bin_capacity.max(1) as f64);
    }

    // NEW: mid-stream tightness bonus — favor near-exact residual matches
    // to item size relative to what other bins could absorb.
    if bin_residual != bin_capacity && bin_residual > 0 {
        let slack_waste = (bin_residual - item_size) as f64;
        if slack_waste < 3.0 {
            score -= 5.0 + (3.0 - slack_waste) * 2.0;
        }
    }

    score
}

