    // early on, waste matters less; later, tight packing is critical.
    let tightness = (norm_pr * (1.0 - norm_pr)).max(0.0); // peaks at half-full residual
    score -= 12.0 * tightness * (0.5 + progress);

    // Quadratic penalty on large residuals, amplified by progress
    score += 0.35 * norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Cubic interaction: reward near-zero residual strongly late in stream
    score -= (1.0 - norm_pr).powi(3) * 8.0 * progress;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits the post residual exactly-ish
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        let slack = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty for trapping space
        score += 3.0 * norm_pr;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins unless
    // all open bins are bad fits; scale with number of open bins and progress.
    if bin_residual == bin_capacity {
        score += 18.0 + 4.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
    }

    // Mean residual alignment: prefer bins whose residual is below mean (tighter)
    if pr < mean_residual {
        score -= 2.0 * (mean_residual - pr) / cap;
    } else {
        score += 1.5 * (pr - mean_residual) / cap;
    }

    score
}

