pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead-space" classes (0..=10, 21..=30, 51..=60) are penalized,
    // leftovers that are highly reusable (11..=20, 31..=50, 61..=100) rewarded.
    let cls = post_residual / 10;
    let class_bonus: f64 = match cls {
        0 => -6.0,                       // near-perfect fill (0..=9)
        1 => -10.0,                      // 10..=19 sweet spot
        2 => 4.0,                        // 20..=29 awkward
        3 => -8.0,                       // 30..=39 good
        4 => -5.0,                       // 40..=49 decent
        5 => 6.0,                        // 50..=59 half-empty penalty
        6 => -3.0,
        7 => 2.0,
        8 => -2.0,
        9 => 1.0,
        _ => -4.0,                       // 100 (new bin candidate) raw
    };
    score += class_bonus;

    // Modulo-10 structure: exact multiples of 10 leftover are ideal targets
    // for the common item sizes; odd leftovers slightly worse.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Integer-division coupling with the lookahead item: reward leftovers
    // that can host the next item with small remainder (good chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = post_residual % next_item_size;
        score -= (next_item_size - chain) as f64 * 0.15;
        // big reward if next item exactly fills the bin
        if chain == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this leftover: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: base penalty grows with stream progress
    // and open bin count, so new bins are opened only when worthwhile.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 + 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // allow opening a new bin if all existing fits are terrible
        if mean_residual < 15.0 && post_residual == bin_capacity {
            score -= 6.0;
        }
    }

    // Congestion term: when many bins compete, prefer tighter fits.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 0.8;
    }

    // Mild pull toward the mean residual to keep bin states balanced.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
