        }
        // New-bin leftover exactly matches next item: strong opening justification.
        if bin_residual == bin_capacity && next_item_size >= item_size && (bin_capacity - item_size) < next_item_size + 4 {
            score += 6.0;
        }
    }

    // ---- Relative-to-mean coupling ----
    score -= 0.38 * (mean_residual - post);
    if post <= mean_residual {
