            score += 8.0;
        }
        if item_size <= 10 && mean_residual > item_size as f64 {
            score += 24.0;
        }
        if item_size <= 25 && mean_residual > item_size as f64 + 5.0 && open_bins_count > 2 {
            score += 7.0;
        }
        // Large items (>= half capacity) with no good home: open a fresh bin.
        if item_size * 2 >= bin_capacity && item_size as f64 > mean_residual {
            score -= 12.0;
        }
    }

    // ---- Tight-fit reward ----
    if bin_residual > 0 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 22.0;
        } else if fill_ratio > 0.7 {
            score -= 9.0;
        } else if fill_ratio < 0.3 {
            score += 8.0;
        }
    }

    // Consolidation pressure grows with progress.
    score += progress * (mean_residual - post) * 0.3;
    // Mild proliferation penalty.
    score += 0.1 * open_bins_count as f64;

    score
}

