            // Next item won't fit in this bin's leftover: leftover is dead
            // unless another bin takes it. Penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance pressure: if this is the only bin that fits the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.8 * progress);

    // Mean-residual coupling: if this bin is much tighter than average,
    // prefer packing it down (reduces fragmentation).
    let tightness = mean_residual - bin_residual as f64;
    score -= tightness * 0.5;

    // New-bin candidate: default is a fresh empty bin. Make it attractive
    // only when existing bins are quite full/fragmented or item is large.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
