        // Cost of opening a new bin; discount when bins are crowded or item huge.
        score = 55.0 - 45.0 * avg_fill - 30.0 * large_item + open_bins_count as f64 * 2.0;
        // Never open a new bin when a perfect fit exists elsewhere.
        if post_residual == 0 { score += 100.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
