        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.1 * bin_residual as f64;
    }

    // New-bin candidate (bin_residual == bin_capacity): it should generally
    // lose against decent fits, but win when all open bins would leave big
    // dead space. Penalize it relative to current mean residual: when open
    // bins are crowded (low mean residual), opening fresh space is cheaper.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the item would leave a huge gap in every existing bin, ease up:
        // compare item's post_residual in existing bins implicitly via mean_residual.
        score -= 0.05 * mean_residual;
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
        // Too many open bins: discourage fragmentation.
        score += 0.4 * open_bins_count as f64;
    } else {
