    // Global pressure: when many bins are open, prefer placements that
    // close out bins (small post_residual already does this); add a small
    // consolidation nudge proportional to mean residual.
    score -= 0.02 * mean_residual * (bin_residual as f64 / bin_capacity as f64);

    score
}

