pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 8 {
        score -= 10.0;
    }

    // 2-step lookahead: chain fits with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 450.0;
        } else if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
            if after_next <= 2 {
                score -= 12.0;
            } else if after_next < 10 {
                score -= 15.0;
            }
        } else {
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.5 * stranded.min(80.0);
        }
    }

    // Dead-space tiers: non-linear penalty for unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 70.0;
    } else if post_residual < 20 {
        score += 28.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Tighter-than-mean bins are preferred.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Fit-ratio term.
    if !is_new_bin && bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 20.0;
        } else if fill_ratio > 0.7 {
            score -= 8.0;
        } else if fill_ratio < 0.3 {
            score += 7.0;
        }
    }

    // Last-chance bin: sole fitting open bin beats opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 160.0;
    }

    // New-bin candidate gating: open only when fits are poor or late stream.
    if is_new_bin {
        score += 16.0 + 5.0 * open_bins_count as f64;
        // Poor fits everywhere: a fresh bin is justified.
        if item_size as f64 > mean_residual - 5.0 {
            score -= 30.0;
        }
        // Late stream: opening bins cheaper than leaving stragglers.
        if progress > 0.85 {
            score -= 14.0;
        }
        // Early stream with many bins: resist proliferation.
        if progress < 0.3 && open_bins_count > 4 {
            score += 10.0;
        }
    }

    // Consolidation pressure grows as the stream progresses.
    score += progress * (mean_residual - post_residual as f64) * 0.25;

    // Slight penalty per open bin.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 130.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 12.0;
    }

    // Dead-space tiers: non-linear penalty for unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 75.0;
    } else if post_residual < 20 {
        score += 30.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // 2-step lookahead: chain fits with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact chain fit is excellent
        } else if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score -= 20.0; // next item nearly fills this bin too
            } else if after_next < 20 {
                score -= 10.0;
            } else {
                score -= 6.0;
            }
            // Refined chain bonus: leftover after next item is itself chainable.
            if after_next > 0 && next_item_size > 0 && after_next >= next_item_size {
                score -= 4.0;
            }
        } else {
            // Next item cannot use the leftover: penalize stranded space.
            let stranded = (next_item_size - post_residual) as f64;
            score += 8.0 + stranded.min(30.0) * 0.3;
        }
        // 3-step lookahead flavor: next item exactly consumes a tight leftover chain.
        if post_residual > next_item_size && (post_residual - next_item_size) <= 2 && (post_residual - next_item_size) > 0 {
            score -= 8.0;
        }
    }

    // Compare against mean residual: tighter bins preferred.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Fit-ratio term: reward tight packing independent of absolute sizes.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 18.0;
        } else if fill_ratio > 0.7 {
            score -= 7.0;
        } else if fill_ratio < 0.3 {
            score += 6.0;
        }
    }

    // Last-chance bin: sole fitting open bin beats opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 65.0;
    }

    // New-bin candidate gating: only open when fits are poor or stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 + 6.0 * open_bins_count as f64;
        // Poor fits everywhere: a fresh bin is justified.
        if (item_size as f64) > mean_residual.min(bin_capacity as f64) - 5.0 {
            score -= 26.0;
        }
        // Late in the stream, opening bins is cheaper than leaving stragglers.
        if progress > 0.85 {
            score -= 12.0;
        }
        // Early stream with many bins: resist proliferation.
        if progress < 0.3 && open_bins_count > 4 {
            score += 8.0;
        }
        // If NO open bin can fit the item at all, a new bin is mandatory.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Consolidation pressure grows as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64) * 0.25;

    // Slight penalty per open bin to discourage proliferation.
    score += 0.1 * open_bins_count as f64;

    // Dead-space ratio refinement: penalize residuals that no plausible item
    // (1..=100) can tightly consume relative to typical item sizes.
    if post_residual > 0 && post_residual < bin_capacity {
        let usable = post_residual as f64 / bin_capacity as f64;
        if usable < 0.05 {
            score += 10.0; // tiny unusable sliver
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Residuals that are "dead" (small, < 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Integer-division thresholds: how many size-10 units remain.
    let units = post_residual / 10;
    // Reward leaving residuals that are multiples of 10 (harmonic alignment),
    // since future items in 1..100 often fit nicely into round residuals.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let next_fit_gap = post_residual - next_item_size;
            score -= 30.0 * (1.0 - next_fit_gap as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder; penalize large leftovers mildly.
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, mild tie-breaking pressure toward tight fit already applied.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and
        // existing residuals are poor fits, or when stream is early (many items remain).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_quality = (mean_residual - item_size as f64).max(0.0);
        // Penalize new bin by default...
        score += 45.0;
        // ...but discount when item is big (would leave tiny dead space elsewhere anyway)
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // ...and when mean residual across open bins is large (existing bins are roomy,
        // so no need for a new one -> keep penalty high). If mean residual is small,
        // existing bins are nearly full, new bin becomes attractive.
        score -= (bin_capacity as f64 - mean_residual).max(0.0) * 0.3;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= (1.0 - progress) * 10.0;
        // Avoid wasted new bins near the end of the stream.
        if progress > 0.9 {
            score += 20.0;
        }
        let _ = avg_fit_quality;
        let _ = units;
    }

    // Discourage spreading across many open bins when residuals are already fragmented.
    if open_bins_count > 8 {
        score += 1.0;
    }

    score
}

