pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual).
    score -= 40.0 * (-post_residual as f64 / 12.0).exp();

    // 2-step lookahead: strong reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits perfectly into this bin's leftover
            score -= 35.0 * (-gap / 8.0).exp();
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // leftover too small for next item: dead space unless tiny
            if post_residual > 0 && post_residual < 10 {
                score -= 10.0; // nearly full bin, fine
            } else {
                score += 8.0 * (post_residual as f64 / 30.0);
            }
        }
    }

    // Compare against mean residual: bins with unusually large residual are
    // better candidates to absorb this item (keep tight bins tight).
    if bin_residual as f64 > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.4;
    } else {
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it when open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 45.0;
        // fewer open bins -> opening new bins is cheaper early on
        score -= (open_bins_count as f64).min(10.0) * 2.0;
        // if the only alternative leaves big unusable gaps, new bin less bad
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
            score -= 15.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

