    // Compare against mean residual: tighter bins preferred.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Fit-ratio term: reward tight packing independent of absolute sizes.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 18.0;
        } else if fill_ratio > 0.7 {
            score -= 7.0;
        } else if fill_ratio < 0.3 {
            score += 6.0;
        }
    }

    // NEW: absolute leftover usability — leftovers that can still hold typical
    // future items are valuable; unusable slivers are dead weight.
    if post_residual > 0 {
        if post_residual > 50 {
            score -= 5.0; // roomy leftover likely reusable
        } else if post_residual < next_item_size.max(1) {
            score += 10.0; // leftover smaller than the next item: stranded
        }
    }

    // Last-chance bin: sole fitting open bin beats opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 65.0;
    }

    // New-bin candidate gating: only open when fits are poor or stream is late.
    if bin_residual == bin_capacity {
        score += 14.0 + 6.0 * open_bins_count as f64;
        // Poor fits everywhere: a fresh bin is justified.
        if (item_size as f64) > mean_residual.min(bin_capacity as f64) - 5.0 {
            score -= 26.0;
        }
        // Late in the stream, opening bins is cheaper than leaving stragglers.
        if progress > 0.85 {
            score -= 12.0;
        }
        // Early stream with many bins: resist proliferation.
        if progress < 0.3 && open_bins_count > 4 {
            score += 8.0;
        }
        // NEW: if the next item is large, a fresh bin reserves room for it.
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 6.0;
        }
    }

    // Consolidation pressure grows as the stream progresses.
    score += progress * (mean_residual - post_residual as f64) * 0.25;

    // Slight penalty per open bin to discourage proliferation.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: minimize wasted space, weighted non-linearly by stream progress.
    let mut score = pr * (0.6 + 1.2 * progress * progress);

