    if post_residual > 0 && post_residual < 10 {
        score += 70.0 * (1.0 - progress);
    } else if post_residual < 20 {
        score += 28.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // Smooth dead-space bump for small-but-nonzero residuals.
    score += 20.0 * prn * (1.0 - prn) * (1.0 - prn) * (1.0 - progress);

    // Mean-residual coupling: tighter bins preferred.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 6.0 * dev * (0.5 + progress);

