pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: how "usable" is post_residual?
    // Class boundaries at multiples of 10 and key fractions of capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit bonus: zero residual is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: leftover smaller than the smallest possible item (1)
    // can never be used; leftover in the "awkward" band (1..=9) is nearly dead.
    if post_residual >= 1 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic classes: leftovers divisible by 10 (or 5) are more likely
    // to host future items drawn from typical integer distributions.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        // Non-harmonic leftover: penalize proportionally to its oddness.
        score += (post_residual % 10) as f64 * 1.5;
    }

    // Big leftover classes: prefer keeping large usable chunks.
    if pr > cap * 0.5 {
        score -= 10.0;
    } else if pr > cap * 0.25 {
        score -= 4.0;
    } else if pr > 0.0 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item fits; the tighter the better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 - slack.min(20.0) * 0.2;
        } else {
            // Next item would NOT fit here: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its raw score is post_residual == capacity, already high; add a
    // dynamic penalty that shrinks as the stream matures or when open bins
    // are all nearly full (mean residual low), making new bins acceptable
