    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual / cap).max(0.0).min(1.0);
        // High mean residual => plenty of room in open bins => penalize new bin.
        score += 40.0 + pressure * 40.0 - progress * 15.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Prefer filling more crowded bins (fewer active bins overall).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

