            score -= 40.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            // Only one fitting bin: compare its likely leftover quality via mean residual
            if mean_residual < 0.25 * cap {
                score -= 10.0; // existing bins are fragmented; fresh bin is fine
