        score += 1.5 * open_bins_count as f64;
    }

    // Prefer tighter existing bins generally (smaller pre-residual => better fit tightness)
    score += 0.02 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Global pressure: when many bins are open and mean residual is low, consolidate.
    score += 0.01 * mean_residual;

    score
}

