    }

    // 2-step lookahead: chain fits with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 62.0; // exact chain fit is excellent
        } else if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 70.0; // double-exact chain: bin closes perfectly
            } else if after_next < 10 {
                score -= 22.0;
            } else if after_next < 20 {
                score -= 11.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item cannot use the leftover: penalize stranded space,
            // scaled by how much of the bin would be dead.
            let stranded = (next_item_size - post_residual) as f64;
            let dead_frac = stranded / bin_capacity as f64;
            score += 8.0 + stranded.min(30.0) * 0.3 + dead_frac * 25.0;
        }
        // 3-step lookahead flavor: next item exactly consumes a tight leftover chain.
        let gap = post_residual as i64 - next_item_size as i64;
        if gap > 0 && gap <= 2 {
            score -= 9.0;
        }
    }

    // Compare against mean residual: tighter bins preferred.
    score -= 0.38 * (mean_residual - post_residual as f64);

    // Fit-ratio term: reward tight packing independent of absolute sizes.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 19.0;
        } else if fill_ratio > 0.7 {
            score -= 7.0;
        } else if fill_ratio < 0.3 {
            score += 6.0;
        }
    }

    // Last-chance bin: sole fitting open bin beats opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 68.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 + 6.0 * open_bins_count as f64;
        // Poor fits everywhere: a fresh bin is justified.
        if (item_size as f64) > mean_residual.min(bin_capacity as f64) - 5.0 {
            score -= 27.0;
        }
        // Late in the stream, opening bins is cheaper than leaving stragglers.
        if progress > 0.85 {
            score -= 13.0;
        }
        // Early stream with many bins: resist proliferation.
        if progress < 0.3 && open_bins_count > 4 {
            score += 9.0;
        }
        // If the next item is large, a fresh bin reserves room for it.
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 5.0;
        }
        // Reserve a fresh bin only if the item leaves awkward residue in ANY
        // existing bin: item would strand >20 units in a typical open bin.
        if next_item_size > 0 && next_item_size < 20 {
            score += 6.0; // small next item fits leftovers easily; avoid new bin
        }
        // Wasted-space ratio guard: if placing here would waste more than
        // half the bin, opening a fresh bin is often better long-term.
        if post_residual * 2 < bin_capacity {
            score -= 10.0;
        }
    }

    // Consolidation pressure grows as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64) * 0.28;

    // Slight penalty per open bin to discourage proliferation.
    score += 0.1 * open_bins_count as f64;

    // New refinement: quadratic dead-space curvature on mid-range leftovers
    // to better discriminate between 20-40 residual bins.
    if post_residual >= 20 && post_residual <= 40 {
        score += ((post_residual - 30) as f64) * ((post_residual - 30) as f64) * 0.05;
    }

    score
}

