    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            if gap == 0.0 {
                // Perfect chain: this placement enables a perfect next fit
                score -= 60.0;
            } else {
                // Partial credit, decaying with gap size
                score -= 40.0 * (1.0 - gap / pr.max(1.0));
            }
        } else {
            // Next item cannot fit here: slight penalty scaled by overflow
            score += 8.0 * ((next - pr) / 100.0);
        }
    }

    // Relative to mean residual: bins tighter than average are precious
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 10.0 * rel.clamp(-2.0, 2.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (dead space below min item size)
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (10.0 - pr);
    }

    // New-bin candidate: only attractive late in the stream or when open bins are full-ish
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
