    // Mean-residual contrast: prefer bins tighter than average.
    score -= 0.38 * (mean_residual - post_residual as f64);

    // Fit-ratio tiers for real (non-empty) bins.
    if bin_residual != bin_capacity {
        if fit_ratio > 0.9 {
