            }
            // If next item would fit the post_residual but not exactly, small bonus.
            if next_item_size <= post_residual {
                score -= 8.0;
            } else {
                // Next item won't fit -> post_residual becomes dead space relative to lookahead.
                score += (next_item_size - post_residual) as f64 * 0.25;
            }
