        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins (small post_residual already in base score).
    // Slight tie-breaker toward bins with fewer total open bins (consolidation).
