    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // coarse capacity fractions (eighths), rewarding residuals that are
    // "reusable" multiples and penalizing dead-space classes.
    let frac = (post_residual * 8) / bin_capacity; // 0..=8 integer division class
    let class_bonus: f64 = match frac {
        0 => -60.0,                     // perfect fit: extremely desirable
        1 => -18.0,                     // tiny reusable sliver
        2 => -30.0,                     // quarter-free: good for small items
        3 => 6.0,                       // awkward 3/8 class
        4 => -25.0,                     // half-free: very reusable
        5 => 4.0,                       // awkward 5/8 class
        6 => -14.0,                     // three-quarters free
        7 => -8.0,                      // nearly empty
        _ => 0.0,                       // empty bin baseline
    };
    score += class_bonus;

    // Modulo-10 harmonic of post_residual: residuals divisible by common
    // item granularities (10, 20) are more likely to be filled later.
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 10.0;
    } else if m10 == 5 {
        score += 2.0;
    } else {
        score += (m10 as f64) * 0.6;    // finer granularity => more dead space
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this bin (perfect 2-chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let nxt_frac = (next_item_size * 8) / bin_capacity;
            score -= (post_residual - next_item_size) as f64 * 0.35;
            if nxt_frac == 0 || nxt_frac == 2 || nxt_frac == 4 {
                score -= 8.0;           // next item lands in a good class
            }
        } else {
            // next item won't fit here; slight penalty if post_residual
            // is too small to ever be useful again (below min item size)
            if post_residual < 10 {
                score += 12.0;
            }
        }
    } else {
        // last item: prefer fullest packing, ignore future reusability
        score += class_bonus * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score -= 15.0;              // even a perfect-fit last chance
        }
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // prefer it when existing bins are crowded or the fit here is bad.
    if bin_residual == bin_capacity {
        score += 30.0;                  // base cost of consuming fresh capacity
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64 + 1.0);
        if mean_residual < 15.0 {
            score -= 35.0;              // open bins nearly full: open new one
        }
        if post_residual == 0 {
            score -= 5.0;
        }
        if progress > 0.8 && crowded > 2.0 {
            score -= 6.0;
        }
    }

    // Mild global pressure: more open bins => consolidate into existing ones.
    score += (open_bins_count as f64) * 0.4;

    // Small tie-breaker on tightness of fit relative to bin residual.
    score += (bin_residual - item_size) as f64 * 0.05;
    score -= (item_size as f64) * 0.1;  // favor placing larger items well

    score
}

