        } else {
            // Next item cannot fit here: penalize dead space that is too small
            // for typical items (below the minimum size 1 => always potentially useful,
            // so scale penalty by how unusable the leftover is).
            let dead = post_residual as f64;
            score += 0.5 * dead;
