    // relative to the mean residual across open bins.
    let fit_tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 50.0 * fit_tightness;

    // Compare post_residual against mean residual: leaving this bin far below
    // mean residual wastes capacity elsewhere; leaving it above mean is fine.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
