    let dispersion = (mean_residual - post_residual as f64).abs();
    score -= 0.40 * (mean_residual - post_residual as f64);
    score -= 0.06 * dispersion;

    // Fit-ratio term with extended granularity.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.95 {
            score -= 24.0;
        } else if fill_ratio > 0.9 {
            score -= 19.0;
        } else if fill_ratio > 0.7 {
            score -= 7.0;
        } else if fill_ratio < 0.3 {
            score += 7.0;
        } else if fill_ratio < 0.45 {
            score += 3.0;
        }
    }

    // Last-chance bin: sole fitting open bin strongly beats a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);

    // New-bin gating with finer progress bands.
    if bin_residual == bin_capacity {
        score += 14.0 + 6.0 * open_bins_count as f64;
        if (item_size as f64) > mean_residual.min(bin_capacity as f64) - 5.0 {
            score -= 29.0;
        }
        if progress > 0.9 {
            score -= 18.0;
        } else if progress > 0.85 {
            score -= 13.0;
        }
        if progress < 0.3 && open_bins_count > 4 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 5.0;
        }
        // Resist opening bins mid-stream when several bins still fit.
        if fitting_bins_count >= 2 && progress < 0.85 {
            score += 13.0;
        }
        // Strong items near capacity justify a fresh bin late in the stream.
        if item_size >= 90 && progress > 0.6 {
            score -= 8.0;
        }
        // Mutation: penalize new bins more when mean residual is still large.
        if mean_residual > item_size as f64 + 8.0 {
            score += 9.0;
        }
    }

    // Consolidation pressure grows with progress.
    score += progress * (mean_residual - post_residual as f64) * 0.30;

    // Mild bin proliferation penalty.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Modulo classes of post_residual: small residues in "nice" bands (multiples
    // of 10, 25, 50) are more likely reusable by future items.
    let pr = post_residual;
    if pr % 10 == 0 { score -= 8.0; }
    if pr % 25 == 0 { score -= 6.0; }
    if pr % 50 == 0 { score -= 6.0; }

    // Integer-division thresholds: dead space in the awkward 1..=10 band is bad,
    // mid-band residue (11..=30) is moderately useful.
    let dead_band = pr / 12; // 0 for pr in 0..=11
    score += 4.0 * (dead_band as f64).min(3.0);

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0) * 0.5;
            if slack % 10 == 0 { score -= 5.0; }
        } else {
            // next item cannot use this bin's residue; penalize by how badly it misses
            score += ((next_item_size - pr) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing unless fit is poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Opening a new bin is attractive if no open bin gives a tight fit.
        if post_residual == bin_capacity - item_size && post_residual > 30 {
            score -= 10.0;
        }
    }

    // Progress-based scaling: late in stream, tighten packing (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // "lonely" tight bin; keep it tight (favor placing here).
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 0.2 * (mean_residual - resid);
    } else {
        score += 0.1 * (resid - mean_residual);
    }

    // Fraction-of-capacity harmonic term: reward residues that are small
    // fractions of capacity (1/2, 1/4, 3/4 style leftovers).
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr == half || pr == quarter || pr == 3 * quarter {
        score -= 10.0;
    }

    score
}

