    }

    let progress = step_index as f64 / (total_items.max(1) as f64);

    // New-bin gating: open only when fits are poor or stream is late.
    if bin_residual == bin_capacity {
        score += 14.0 + 6.0 * open_bins_count as f64;
        if (item_size as f64) > mean_residual.min(bin_capacity as f64) - 5.0 {
