        if fitting_bins_count >= 2 && progress < 0.85 {
            score += 13.0;
        }
        // Large items deserve fresh bins early: avoid fragmenting them.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 5.0;
