    }

    // Consolidation pressure grows with progress.
    score += progress * (mean_residual - post_residual as f64) * 0.30;

    // Mild bin proliferation penalty.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual penalty scaled by item size.
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Reward bins where the item fills a large fraction of the residual.
    let fill_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= fill_ratio * fill_ratio * 25.0;

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack_after_next * 0.15;
        } else {
            // Next item won't fit here; penalize leaving awkward medium residuals.
            let awkward = if post_residual < next_item_size && post_residual < 20 {
                12.0
            } else {
                4.0
            };
            score += awkward;
        }
    } else {
        // Last item: minimize residual directly, no future to plan for.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let poor_fit = (post_residual as f64 / bin_capacity as f64) - (item_size as f64 / bin_capacity as f64);
