        score += 55.0 - progress * 10.0;
        // If mean residual across open bins is small, opening fresh is more attractive.
        score -= (mean_residual / 10.0).min(15.0);
        // If this bin is the only fitting bin, discourage opening a new bin implicitly
        // via the last-chance subtraction above; add mild penalty here for balance.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
        let _ = poor_fit;
    } else {
        // Prefer bins whose residual deviates below the mean (denser bins first).
        let dev = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score -= dev * 15.0;
        // Mild preference for fewer open bins (packing denser existing stock).
        score += (open_bins_count as f64) * 0.05;
    }

    // Dead-space avoidance: residuals too small to ever be useful are penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

