pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in a
    // "useful" residue class (small, or divisible into common item sizes)
    // are rewarded. Classes based on integer division thresholds.
    let pr = post_residual;
    let class = pr / 10; // coarse harmonic class (0..=9)
    match class {
        0 => score -= 12.0,                    // near-perfect fit
        1 => score -= 8.0,                     // excellent leftover
        2 => score -= 4.0,                     // good leftover
        3 | 4 => score -= 1.0,                 // moderate leftover
        5 | 6 => score += 3.0,                 // awkward mid gap
        _ => score += 6.0,                     // large dead space
    }

    // Modulo arithmetic: residuals that are multiples of small common sizes
    // (e.g. divisible by 10 or 20) are more likely to be filled later.
    if pr > 0 && (pr % 10 == 0) {
        score -= 3.0;
    }
    if pr > 0 && (pr % 20 == 0) {
        score -= 2.0;
    }

    // Lookahead coupling: penalize if the next item cannot use this bin's
    // post residual but could use other bins' residuals; reward if it fits.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward proportionally to tightness
            let lookahead_tightness = (pr - next_item_size) as f64;
            score -= 6.0 - 0.15 * lookahead_tightness;
        } else {
            // wasted opportunity: this bin's leftover won't serve next item
            score += 0.05 * (next_item_size as f64 - pr as f64);
