    // Slight preference for bins whose residual is close to the mean:
    // keeps residual distribution balanced across bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Tiny tie-break favoring fuller bins.
    score -= 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

