pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it decomposes into
    // "nice" denominations (divisors of capacity). Residuals divisible by
    // 50/25/20/10 are more reusable by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that sit on harmonic grid points.
    if post_residual % 50 == 0 { score -= 6.0; }
    else if post_residual % 25 == 0 { score -= 4.0; }
    else if post_residual % 20 == 0 { score -= 3.0; }
    else if post_residual % 10 == 0 { score -= 2.0; }

    // Penalize awkward residual classes via modulo coupling.
    let awkward = (post_residual % 7) as f64;
    score += 0.3 * awkward;

    // Perfect fit is always excellent.
    if post_residual == 0 { score -= 15.0; }

    // Dead-space penalty: tiny residuals are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let fill_ratio = nxt / pr.max(1.0);
            // reward high fill of the leftover, penalize leaving tiny crumbs
            score -= 4.0 * fill_ratio;
            let crumb = pr - nxt;
            if crumb > 0.0 && crumb < 10.0 {
                score += 5.0;
            }
            // harmonic check of the crumb after the lookahead item
            let crumb_u = crumb as u32;
            if crumb_u % 25 == 0 || crumb_u % 20 == 0 { score -= 2.0; }
        } else {
            // next item won't fit here; residual will carry forward.
            // Slight penalty proportional to how far off it is, scaled
            // by stream progression (early on, keep bins flexible).
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 2.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: default score is full capacity residual (100).
    // Only prefer a new bin when the best existing fit is very poor.
    if bin_residual == bin_capacity {
        // neutralize base, then evaluate: opening a new bin is attractive
        // if item is large and would leave huge unusable space elsewhere,
        // but wasteful when many bins are lightly loaded.
        score = 0.0;
        score += 20.0 * (item_size as f64 / cap); // large items prefer existing bins
        score -= 1.5 * open_bins_count as f64;    // many open bins -> reuse them
        score += if mean_residual > 40.0 { 6.0 } else { 0.0 };
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 3.0; // fresh bin can chain with next item
        }
        // small harmonic bonus for a fresh bin's residual class
        if item_size % 25 == 0 || item_size % 20 == 0 { score -= 2.0; }
    }

    // Mild preference for tighter bins overall (waste minimization).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

