pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * (0.5 + 1.5 * p2) + 0.25 * p3;
    score += 40.0 * coupling;

    // Reward tight fits more strongly late in the stream
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (10.0 + 30.0 * p2);

    // Penalize large residual relative to mean residual (dead space asymmetry)
    if mean_residual > 0.0 {
        let ratio = norm_pr * cap / mean_residual;
        score += 5.0 * (ratio - 1.0) * (ratio - 1.0) * (0.3 + 0.7 * progress);
    }

    // Lookahead: reward leaving room for next item, smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        let slack = ((pr - nxt) / cap).max(0.0);
        score -= fit_next * (8.0 - 12.0 * slack * slack) * (0.5 + 0.5 * progress);
        score += (1.0 - fit_next) * 15.0 * (1.0 - progress);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty for proliferation of open bins
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 * (1.0 - progress));

    // New-bin candidate: neutral baseline with slight early-stream preference
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) + 10.0 * progress;
    }

    score
}

