pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: how "usable" is the leftover space? ---
    // Residuals are bucketed by harmonic fractions of capacity (1/2, 1/3, 1/4, 1/5).
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = post_residual as f64;

    // Harmonic class bonus: leftover divisible into "expected" future chunk sizes
    // is more valuable. Class = which harmonic fraction the residual lands in.
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit: heavily reward
    } else if prf > cap * 0.5 {
        0.0 // large residual, still flexible
    } else if prf > cap / 3.0 {
        -6.0 // moderately usable
    } else if prf > cap / 4.0 {
        4.0 // getting awkward
    } else if prf > cap / 5.0 {
        8.0
    } else {
        12.0 // tiny dead space
    };
    score += class_bonus;

    // --- Modulo arithmetic on post_residual: common item-size residues pack better ---
    // If residual is a multiple of 10, future items (often multiples of 10 in many
    // streams) can fill it exactly.
    if pr % 10 == 0 {
        score -= 5.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    }

    // Integer-division threshold: residual / next_item_size tells if the next
    // item fits exactly or with waste.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == pr {
            score -= 25.0; // next item fills this bin perfectly
        } else if next_item_size < pr {
            let fits_ratio = n / prf;
            if fits_ratio > 0.8 {
                score -= 10.0; // near-perfect fill by lookahead item
            } else if fits_ratio < 0.25 {
                score += 4.0; // next item would leave a big hole here
            }
        } else {
            // next item does NOT fit here: residual is dead space relative to lookahead
            score += 6.0;
        }
        // Harmonic pairing: residual + next item == capacity means chained perfection
        if pr + next_item_size == bin_capacity {
            score -= 30.0;
        }
    } else {
        // Last item: prefer to close bins tightly
        score += prf * 0.3;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of opening a new bin. Only attractive when
        // existing bins are all poor fits or fragmented.
        let openness = open_bins_count as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalty grows with number of open bins (avoid bin proliferation)
        let mut new_bin_score = cap as f64 * 0.45 + openness * 3.0 + progress * 5.0;
        // If mean residual is small (bins are full-ish), new bin is reasonable
        if mean_residual < 15.0 {
            new_bin_score -= 10.0;
        }
        // If the item is large relative to mean residual, existing fits are tight anyway
        if (item_size as f64) > mean_residual {
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    } else {
        // Real bin: reward tight fits (small post_residual relative to item)
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 8.0;
    }

    // --- Mild step-dependent drift: late in the stream, consolidate harder ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += prf * (0.05 + 0.10 * progress);

    score
}

