    // integer-division buckets over capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 8.0).floor() as i64; // 0..8 harmonic bucket

    // Reward small residuals (tight packing) non-linearly.
