    // Dead-space penalty: residuals that are too small for the smallest
    // plausible future item (<= 10) are worthless.
    if post_residual < 10 {
        score += 25.0;
    }

    // Harmonic sweet spots: residuals in classes that commonly match
    // future items (e.g. ~25, ~50, ~75) are valuable; reward them.
    match class {
        2 => score -= 8.0, // residual ~25..37
        4 => score -= 10.0, // residual ~50..62
        6 => score -= 6.0,  // residual ~75..87
        0 => score += 4.0,  // nearly full bin: fine but no flexibility
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer chains leaving a harmonic-class remainder.
            let next_class = (slack / cap * 8.0).floor() as i64;
            let bonus = match next_class {
