            // Next item won't fit here; mild penalty proportional to gap.
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (item_size as f64 / cap) * 8.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline that keeps
    // it attractive only when no open bin offers a good (harmonic) fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening new bins is cheaper (fewer future
        // chances to reuse them), so relax the penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
        // If many bins are open and mean residual is high, prefer reusing.
        score += (open_bins_count as f64).min(10.0) * 1.5;
        score += (mean_residual / cap).min(1.0) * 10.0;
    }

