        if post_residual % 25 == 0 { score -= 2.0; }
        if post_residual % 50 == 0 { score -= 2.0; }
    }

    // Mild preference for filling bins earlier in the stream (keeps the
    // open-bin population lean).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / cap) * 4.0;

    score
}

