    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 14.0;
    } else if post_residual <= 12 {
        score -= 4.0;
    }

    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    } else if post_residual < 20 {
        score += 34.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        score -= 6.0;
    }

    // Multi-step lookahead with chain-fit rewards, plus two-item chain anticipation.
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 68.0;
        } else if post_residual > next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score -= 24.0;
            } else if after_next < 20 {
                score -= 12.0;
            } else {
                score -= 6.0;
            }
            if after_next <= 2 {
                score -= 10.0;
            }
            // Two-item chain: next item exactly fills the remainder left after this one.
            if after_next > 0 && after_next == next_item_size {
                score -= 14.0;
            }
        } else {
            let stranded = (next_item_size - post_residual) as f64;
            score += 8.0 + stranded.min(30.0) * 0.32;
        }
        // Penalize bins whose residual is slightly too small for next item (waste trap).
        if post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 3 {
            score += 12.0;
        }
    }

    // Mean-residual coupling with dispersion proxy.
    let dispersion = (mean_residual - post_residual as f64).abs();
    score -= 0.40 * (mean_residual - post_residual as f64);
    score -= 0.06 * dispersion;

    // Fit-ratio term with extended granularity.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.95 {
            score -= 24.0;
        } else if fill_ratio > 0.9 {
            score -= 19.0;
        } else if fill_ratio > 0.7 {
            score -= 7.0;
        } else if fill_ratio < 0.3 {
            score += 7.0;
        } else if fill_ratio < 0.45 {
            score += 3.0;
        }
    }

    // Last-chance bin: sole fitting open bin strongly beats a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);

    // New-bin gating with finer progress bands.
    if bin_residual == bin_capacity {
        score += 14.0 + 6.0 * open_bins_count as f64;
        if (item_size as f64) > mean_residual.min(bin_capacity as f64) - 5.0 {
            score -= 29.0;
        }
        if progress > 0.9 {
            score -= 18.0;
        } else if progress > 0.85 {
            score -= 13.0;
        }
        if progress < 0.3 && open_bins_count > 4 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 5.0;
        }
        // Resist opening bins mid-stream when several bins still fit.
        if fitting_bins_count >= 2 && progress < 0.85 {
            score += 13.0;
        }
        // Strong items near capacity justify a fresh bin late in the stream.
        if item_size >= 90 && progress > 0.6 {
            score -= 8.0;
        }
        // Prefer a fresh bin over a near-empty one when next item is large.
        if next_item_size > 0 && next_item_size as f64 > mean_residual + 10.0 {
            score -= 6.0;
        }
        // Mutation: a fresh bin is attractive when the next item is huge and no open
        // bin will have room for it after this placement.
        if next_item_size > 0 && next_item_size >= 80 && next_item_size > post_residual {
            score -= 4.0;
        }
    }

    // Mutation: reward bins whose residual becomes exactly the mean residual
    // (harmonious fill, keeps future fits predictable).
    if post_residual > 0 && (post_residual as f64 - mean_residual).abs() < 1.0 {
        score -= 6.0;
    }

    // Consolidation pressure grows with progress.
    score += progress * (mean_residual - post_residual as f64) * 0.30;

    // Mild bin proliferation penalty.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins that get closed exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead-space penalty: quadratic in leftover waste.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize proportionally to wasted gap.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.5 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or existing bins are crowded/fragmented.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when existing residuals are small (crowded) or item is big.
        let openness = (crowding * 0.7 + item_frac * 0.5 - 0.35).max(0.0);
        score = 60.0 - 80.0 * openness;
        // Early in the stream, keep bins open longer to allow packing.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * (1.0 - progress);
    }

    // Slight preference to fill fuller bins (lower residual) among equals.
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Mild penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: near-absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear dead-space tiers: tiny unusable fragments are penalized,
        // but a residual that still holds something small is mildly rewarded.
        if post_residual < 5 {
            score += 55.0; // almost certainly wasted space
        } else if post_residual < 10 {
            score += 14.0;
        } else if post_residual < 20 {
            score += 5.0;
        } else {
            score -= 4.0; // roomy residual keeps options open
        }
    }

    // 2-step lookahead: reward bins that can also host the next item,
    // with a bonus when the chain leaves an almost-empty remainder.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 620.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            let mut chain_bonus = 160.0 - slack * 0.45;
            if slack < 8.0 {
                chain_bonus += 25.0; // near-perfect double fit
            }
            score -= chain_bonus;
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.7; // next item stranded if placed here
        }
    }

    // Fit-ratio coupling: how well the item fills this bin's residual.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.9 {
            score -= 45.0;
        } else if fill_ratio > 0.7 {
            score -= 16.0;
        } else if fill_ratio < 0.3 {
            score += 9.0; // careless sprinkle into a roomy bin
        }
    }

    // Mean-residual coupling: prefer filling bins that are already low
    // (stranded bins), gently penalize raiding the roomiest bins.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let below_mean = mean_residual - resid_f;
        if below_mean > 0.0 {
            score -= below_mean * 0.55;
        } else {
            score += (-below_mean) * 0.12;
        }
    }

    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Last-chance bin: sole fitting open bin strongly beats a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 320.0;
    } else if fitting_bins_count == 2 && progress > 0.5 {
        // Late stream: with few options, consolidate rather than proliferate.
        score -= 60.0;
    }

    // New-bin candidate gating.
    if bin_residual == bin_capacity {
        let mut penalty = 55.0 + 4.0 * open_bins_count as f64;

        // A fresh bin is excellent if the current item plus the next item
        // nearly fill it — commit to a dedicated pair-bin.
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair >= bin_capacity as f64 * 0.95 {
                penalty -= 420.0;
            } else if pair >= bin_capacity as f64 * 0.8 {
                penalty -= 140.0;
            }
        }

        // Large item relative to mean residual: open bins are mostly too
        // cramped, so a new bin is less wasteful.
        if (item_size as f64) > mean_residual - 5.0 {
            penalty -= 45.0;
        }

        // Early stream: opening bins is cheap and enables better fits later.
        if progress < 0.25 {
            penalty -= 25.0;
        }
        // Late stream: consolidate aggressively into what exists.
        if progress > 0.85 {
            penalty += 45.0;
        }

        // If several bins already fit the item, refuse a new bin.
        if fitting_bins_count >= 2 {
            penalty += 90.0;
        }

        score += penalty;
    }

    // Mild global proliferation pressure that grows over the stream.
    score += open_bins_count as f64 * (0.05 + 0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: superlinear preference for small post_residual.
    let tightness = (post / cap).powi(3);
    score += 40.0 * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward when the next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fill_ratio = nxt / post.max(1.0);
            score -= 25.0 * fill_ratio * (1.0 - progress);
        } else {
            // Penalize leaving residual that cannot serve the next item.
            score += 12.0 * ((nxt - post) / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate handling: only attractive early or when open bins are very full.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post).abs();
        let crowding = (open_bins_count as f64).ln().max(1.0);
        let penalty = 45.0 + 55.0 * progress + 8.0 * crowding + 10.0 * (mean_residual / cap);
        score += penalty;
        if item_size as f64 / cap > 0.6 {
            score -= 30.0 * progress; // big items: opening fresh space is more acceptable
        }
        let _ = mean_gap;
    } else {
        // Slight preference for bins whose residual is close to the mean (balance).
        score += 5.0 * ((bin_residual as f64 - mean_residual) / cap).abs();
    }

    // Smooth stream-progress coupling: later in the stream, waste is costlier.
    score += 15.0 * (post / cap) * progress * (1.0 - (post / cap));

    score
}

