pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space ---
    // Class 0: post_residual in 0..=10  -> near-perfect fit, strongly reward
    // Class 1: 11..=20                  -> usable for small items
    // Class 2: 21..=50                  -> mediocre dead zone
    // Class 3: 51..=100                 -> large waste, heavy penalty
    let post = post_residual as f64;
    let class = if post_residual <= 10 { 0.0 }
        else if post_residual <= 20 { 1.0 }
        else if post_residual <= 50 { 2.0 }
        else { 3.0 };

    // Quadratic waste penalty scaled by class
    score += class * (post * post) / (bin_capacity as f64);

    // Perfect / near-perfect fit bonus (subtract)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // --- Harmonic coupling with the lookahead item (k=2) ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // The leftover can host the next item: reward proportionally to how
        // snugly it would fit (harmonic residue of next item in post_residual).
        let slack = (post_residual - next_item_size) as f64;
        let snug = 1.0 - slack / (bin_capacity as f64);
        score -= 12.0 * snug;
        // Modulo harmony: leftover divisible-ish by next item size classes
        if post_residual % next_item_size.max(1) <= 5 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Leftover too small for the next item: it is likely dead space.
        score += 6.0 + 0.15 * post;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only open bin that fits; strongly prefer using it
        // unless the waste would be catastrophic.
        score -= 18.0;
        if post_residual > 40 {
            score += 12.0; // soften: maybe a fresh bin is better
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin grows with number of open bins.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheap; late, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If the item is large, a fresh bin is natural (small waste).
        score -= 0.10 * item_size as f64;
        // If mean residual of open bins is small, open bins are nearly full;
        // opening a new one is reasonable.
        score -= 0.05 * mean_residual;
    }

    // --- Mean-residual context ---
    // Prefer bins whose residual is far below the mean (they are the "odd"
    // bins we want to close out), penalize bins near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // --- Integer-division threshold on item size (harmonic classes of items) ---
    let item_class = item_size / 20; // 0..4
    match item_class {
        0 => score -= 2.0,   // tiny items fit almost anywhere
        1 => score += 0.0,
        2 => score += 1.0,
        3 => score += 2.0,
        _ => score += 3.0,   // huge items: prefer tightest bin (post_residual term dominates)
    }

    score
}

